static int xlgmac_all_poll ( struct napi_struct * napi , int budget ) { struct xlgmac_pdata * pdata = container_of ( napi , xlgmac_pdata , napi ) ; struct xlgmac_channel * channel ; int processed , last_processed ; int ring_budget ; unsigned int i ; XLGMAC_PR ( "budget=%d\n" , budget ) ; processed = 0 ; { last_processed = processed ; channel = pdata -> channel_head ; for ( i = 0 ; i < pdata -> channel_count ; i ++ , channel ++ ) { xlgmac_tx_poll ( channel ) ; if ( ring_budget > ( budget - processed ) ) { ring_budget = budget - processed ; } processed += xlgmac_rx_poll ( channel , ring_budget ) ; } } ( processed < budget ) && ( processed != last_processed ) ; if ( processed < budget ) { napi_complete_done ( napi , processed ) ; xlgmac_enable_rx_tx_ints ( pdata ) ; } XLGMAC_PR ( "received = %d\n" , processed ) ; return processed ; } 